#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;
const int MAXN = 1e6 + 5;

ll fact[MAXN], inv_fact[MAXN], inv[MAXN];

void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1] * i % MOD;
    inv[1] = 1;
    for (int i = 2; i <= n; ++i) inv[i] = MOD - (MOD/i) * inv[MOD%i] % MOD;
    inv_fact[0] = inv_fact[1] = 1;
    for (int i = 2; i <= n; ++i) inv_fact[i] = inv_fact[i-1] * inv[i] % MOD;
}

ll C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD;
}

int main() {
    int n, k;
    scanf("%d%d", &n, &k);
    if (n == 1) {
        puts("0");
        return 0;
    }
    precompute(n);
    ll ans = 0;
    for (int m = 1; m < n; ++m) {
        ll ways = C(n-1, m-1) * fact[m] % MOD * fact[n-1-m] % MOD;
        if (m - 1 < k) {
            ans = (ans + ways) % MOD;
        } else {
            ll invalid = C(m-1, k) * fact[k] % MOD * fact[n-1-k] % MOD;
            ans = (ans + ways - invalid + MOD) % MOD;
        }
    }
    printf("%lld\n", ans);
    return 0;
}
