using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;
const int MAXN = 1e6 + 5;

ll fact[MAXN], inv_fact[MAXN];

ll mod_pow(ll a, ll b) {
    ll res = 1;
    while (b > 0) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    inv_fact[n] = mod_pow(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i) {
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD;
    }
}

ll C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    precompute(n);
    ll ans = 0;
    for (int m = 1; m < n; ++m) {
        int t = n - m;
        if (t < k) continue;
        ll ways = C(n - 1, m - 1);
        ways = ways * fact[m - 1] % MOD;
        ways = ways * fact[n - m] % MOD;
        ans = (ans + ways) % MOD;
    }
    cout << ans << endl;
    return 0;
}
