#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1e9 + 7;
const int MAXN = 1e6 + 10;

long long fact[MAXN], inv_fact[MAXN];

long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp /= 2;
    }
    return result;
}

void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    inv_fact[n] = mod_pow(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD;
    }
}

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return (fact[n] * inv_fact[k] % MOD) * inv_fact[n - k] % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    cin >> n >> k;

    if (n == 1) {
        cout << 0 << endl;
        return 0;
    }

    precompute(n);

    long long ans = 0;

    // Case 1: n is in position 1
    // The remaining n-1 elements can be in any order
    ans = (ans + fact[n - 1]) % MOD;

    // Case 2: n is in position p (2 <= p <= n)
    // We need to count permutations where the function returns before reaching n
    // This means there exists a sequence of k elements after the current max (which is < n)
    // before n is encountered

    // For each position p of n (from 2 to n), we need to count:
    // - The number of ways to arrange elements before n such that
    //   the function doesn't return early
    // - The number of ways to arrange elements after n (which don't matter)

    // Actually, let's think differently:
    // The function returns early if it encounters k consecutive elements
    // that are all less than the current maximum, before seeing n.

    // For n at position p:
    // Elements before n: positions 1 to p-1
    // Elements after n: positions p+1 to n

    // The function processes elements left to right.
    // If n is at position p, the function will process elements 1 to p.
    // For the function to return early (before reaching n),
    // there must be k consecutive elements < current max among positions 1 to p-1.

    // But if the function doesn't return early, it will reach n and return n.
    // So we want permutations where the function DOES return early.

    // Wait, we want permutations where the function does NOT return n.
    // So we want permutations where the function returns early.

    // For n at position p:
    // The function processes elements 1 to p.
    // If it returns early, it returns some value < n.
    // For it to return early, there must be k consecutive elements
    // less than the current max among the first p-1 elements.

    // But actually, the function might also not return early and reach n.
    // We want to count permutations where it returns early.

    // Let's reconsider:
    // Total permutations = n!
    // Permutations where function returns n = permutations where function doesn't return early
