#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << endl;
        return 0;
    }
    vector<long long> fact(n + 1, 1);
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % MOD;
    vector<long long> inv(n + 1, 1);
    inv[n] = 1;
    long long denom = fact[n];
    long long inv_denom = 1;
    long long base = denom, exp = MOD - 2;
    while (exp) {
        if (exp & 1) inv_denom = inv_denom * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    inv[n] = inv_denom;
    for (int i = n - 1; i >= 0; --i)
        inv[i] = inv[i + 1] * (i + 1) % MOD;
    auto C = [&](int a, int b) -> long long {
        if (b < 0 || b > a) return 0;
        return fact[a] * inv[b] % MOD * inv[a - b] % MOD;
    };
    long long ans = 0;
    for (int m = 1; m <= n; ++m) {
        if (m - 1 < k) continue;
        int a = m - 1 - k;
        long long ways = C(m - 1, k) * fact[a] % MOD;
        ways = ways * fact[n - m] % MOD;
        ways = ways * C(n - 1, m - 1) % MOD;
        ans = (ans + ways) % MOD;
    }
    cout << ans << endl;
    return 0;
}
